package com.smarthealth.ai;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import com.smarthealth.exception.AIServiceException;import java.net.URI;import java.net.http.*;import java.time.Duration;
 /** Legacy Anthropic client retained for configurable compatibility. */public class ClaudeAIService implements AIService{private final String key,url,model;private final HttpClient client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8)).build();private final ObjectMapper mapper=new ObjectMapper();public ClaudeAIService(String k,String u,String m){key=k;url=u;model=m;}public String getRiskAssessment(String prompt){for(int attempt=0;attempt<2;attempt++)try{ObjectNode body=mapper.createObjectNode();body.put("model",model);body.put("max_tokens",500);body.putArray("messages").addObject().put("role","user").put("content",prompt);HttpRequest req=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(20)).header("x-api-key",key).header("anthropic-version","2023-06-01").header("content-type","application/json").POST(HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body))).build();HttpResponse<String> res=client.send(req,HttpResponse.BodyHandlers.ofString());if(res.statusCode()<200||res.statusCode()>=300)throw new IllegalStateException("AI provider returned HTTP "+res.statusCode());return mapper.readTree(res.body()).path("content").get(0).path("text").asText();}catch(Exception e){if(attempt==1)throw new AIServiceException("AI assessment unavailable",e);try{Thread.sleep(350);}catch(InterruptedException x){Thread.currentThread().interrupt();throw new AIServiceException("AI request interrupted",x);}}throw new AIServiceException("AI assessment unavailable");}}
